// Vendored SPDX license metadata. The entry array below is machine-generated
// by `lib/scripts/generate-data.ts` from the SPDX workgroup's own published
// catalog, committed at `lib/data/spdx-licenses.json`
// (https://github.com/spdx/license-list-data), CC0-1.0, which republishes the
// SPDX License List (https://spdx.org/licenses/). Do not edit the array by
// hand — run the generator to refresh it, which rewrites only the byte span
// between the markers.
//
// The entries are tuples rather than objects: `[id, name, flags]`, with the
// same 721 ids the `licenseIds.ts` catalog carries. Repeating three object
// keys 721 times would cost consumers roughly 20KB of shipped bytes for no
// information. `reference` is deliberately NOT vendored — every upstream
// entry's URL is exactly `https://spdx.org/licenses/<id>.html`, so it is
// templated in `License.referenceUrl`; the generator asserts that template
// against upstream for every id and fails loudly on any deviation, which
// keeps the templating a checked invariant rather than an assumption.

/** Bit set in a metadata entry's `flags` when the license is OSI-approved. @internal */
export const META_FLAG_OSI_APPROVED = 1;

/** Bit set in a metadata entry's `flags` when the license is FSF-libre. @internal */
export const META_FLAG_FSF_LIBRE = 2;

/**
 * One vendored metadata entry: the SPDX identifier, its full title, and the
 * approval bitfield ({@link META_FLAG_OSI_APPROVED} | {@link META_FLAG_FSF_LIBRE}).
 *
 * @internal
 */
export type LicenseMetaEntry = readonly [id: string, name: string, flags: number];

/**
 * One row per license, TAB-separated as `id\tname\tflags`.
 *
 * @remarks
 * A row is a single string rather than a tuple because **a formatter cannot
 * break a string literal.** The longest SPDX name is 88 characters, which
 * overflows the 120-column limit once the id and flags are appended, so a
 * tuple form gets re-wrapped by Biome — and the generator then rewrites it
 * back. Neither shape is a fixpoint and regeneration reports a spurious diff
 * forever. TAB cannot occur in an SPDX name, so the split is unambiguous.
 *
 * @internal
 */
